{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/post-actions.json
    The calls to action of a post header: share and save side by side, one wide read button, or a wide read button with share and save as icons.
    Props (p): labels, mode. *}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_mode = ($p['mode'] ?? 'pair')}
{if og_t(og_eq($v_mode, 'pair'))}
  {capture $c_3}
    {capture $c_1}
      {=og_include('icons/LucideIcon.latte', ['name' => 'share-2', 'size' => 16])|noescape}
      {=og_text(og_get($v_labels, ['share']))}
    {/capture}
    {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'default', 'class' => 'gap-2', 'children' => (string) $c_1])|noescape}
    {capture $c_2}
      {=og_include('icons/LucideIcon.latte', ['name' => 'bookmark', 'size' => 16])|noescape}
      {=og_text(og_get($v_labels, ['save']))}
    {/capture}
    {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'default', 'class' => 'gap-2', 'children' => (string) $c_2])|noescape}
  {/capture}
  {=og_include('compose/Group.latte', ['gap' => '2', 'class' => 'flex-wrap', 'attrs' => og_attrs(['data-slot', 'post-actions']), 'children' => (string) $c_3])|noescape}
{else}
  {capture $c_7}
    {capture $c_4}
      {=og_include('icons/LucideIcon.latte', ['name' => 'book-open', 'size' => 16])|noescape}
      {=og_text(og_get($v_labels, ['read']))}
    {/capture}
    {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'default', 'class' => 'gap-2 flex-1', 'children' => (string) $c_4])|noescape}
    {if og_t(og_eq($v_mode, 'icons'))}
      {capture $c_5}
        {=og_include('icons/LucideIcon.latte', ['name' => 'share-2', 'size' => 16])|noescape}
      {/capture}
      {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'default', 'layout' => 'icon', 'ariaLabel' => og_s(og_get($v_labels, ['share'])), 'children' => (string) $c_5])|noescape}
      {capture $c_6}
        {=og_include('icons/LucideIcon.latte', ['name' => 'bookmark', 'size' => 16])|noescape}
      {/capture}
      {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'default', 'layout' => 'icon', 'ariaLabel' => og_s(og_get($v_labels, ['save'])), 'children' => (string) $c_6])|noescape}
    {/if}
  {/capture}
  {=og_include('compose/Group.latte', ['gap' => '2', 'attrs' => og_attrs(['data-slot', 'post-actions']), 'children' => (string) $c_7])|noescape}
{/if}
